package com.powercms.cms.sitepackage;
import com.fasterxml.jackson.databind.JsonNode; import com.powercms.cms.content.repo.ContentItemRepository; import com.fasterxml.jackson.databind.ObjectMapper; import com.powercms.cms.model.repo.ContentTypeRepository; import com.powercms.cms.sitepackage.repo.*; import com.powercms.cms.widget.repo.WidgetDefinitionRepository; import com.powercms.common.error.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class ComponentNormalizer { static final int MAX_BYTES=256*1024,MAX_DEPTH=24; private final ObjectMapper mapper; private final ContentTypeRepository types; private final SharedComponentRepository shared; private final SiteContainerRepository containers; private final WidgetDefinitionRepository widgets; private final ContentItemRepository items; ComponentNormalizer(ObjectMapper m,ContentTypeRepository t,SharedComponentRepository s,SiteContainerRepository c){this(m,t,s,c,null,null);} @org.springframework.beans.factory.annotation.Autowired ComponentNormalizer(ObjectMapper m,ContentTypeRepository t,SharedComponentRepository s,SiteContainerRepository c,WidgetDefinitionRepository w,ContentItemRepository i){mapper=m;types=t;shared=s;containers=c;widgets=w;items=i;}
 public ComponentInstance normalize(UUID siteId,ComponentInstance input,int order){if(input==null||input.kind()==null)throw bad("kind required");String id=input.id();try{UUID.fromString(id);}catch(Exception e){throw bad("id must be UUID");}Map<String,Object> additional=object(input.additionalModel());check(additional);if(input.kind()==ComponentInstance.Kind.CONTENT){if(input.contentItemId()==null||items==null)throw bad("contentItemId required");var item=items.findById(input.contentItemId()).filter(x->siteId.equals(x.getSiteId())&&!"ARCHIVED".equals(x.getStatus())).orElseThrow(()->bad("content item site mismatch or unavailable"));types.findById(item.getContentTypeId()).filter(t->siteId.equals(t.getSiteId())&&!"PAGE".equalsIgnoreCase(t.getObjectType())).orElseThrow(()->bad("content item type is not placeable"));return new ComponentInstance(id,input.kind(),null,null,item.getContentTypeId(),item.getTitle(),Map.of(),null,null,additional,order,null,Map.of(),item.getId(),input.contentVersion());}if(input.kind()==ComponentInstance.Kind.WIDGET){if(input.widgetId()==null||widgets==null)throw bad("widgetId required");widgets.findById(input.widgetId()).filter(x->siteId.equals(x.getSiteId())&&"PUBLISHED".equals(x.getStatus())).orElseThrow(()->bad("published widget required"));Map<String,Object> params=object(input.widgetParams());check(params);return new ComponentInstance(id,input.kind(),null,null,null,input.title(),Map.of(),null,null,additional,order,input.widgetId(),params,null,null);}if(input.kind()==ComponentInstance.Kind.SHARED){if(input.sharedComponentId()==null)throw bad("sharedComponentId required");var ref=shared.findById(input.sharedComponentId()).filter(x->siteId.equals(x.getSiteId())).orElseThrow(()->bad("shared component site mismatch ??"));return new ComponentInstance(id,input.kind(),ref.getId(),input.sharedVersion(),ref.getContentTypeId(),input.title(),Map.of(),null,null,additional,order,null,Map.of(),null,null);}if(input.componentTypeId()==null)throw bad("componentTypeId required");types.findById(input.componentTypeId()).filter(t->siteId.equals(t.getSiteId())&&"COMPONENT".equalsIgnoreCase(t.getObjectType())).orElseThrow(()->bad("component type site mismatch"));Map<String,Object> data=object(input.data());check(data);String path=normalizeTemplate(input.templatePath());if(input.containerId()!=null)containers.findById(input.containerId()).filter(c->siteId.equals(c.getSiteId())).orElseThrow(()->bad("container site mismatch"));return new ComponentInstance(id,input.kind(),null,null,input.componentTypeId(),input.title(),data,path,input.containerId(),additional,order,null,Map.of(),null,null);}
 private Map<String,Object> object(Map<String,Object> v){return v==null?Map.of():new LinkedHashMap<>(v);}private void check(Object v){try{JsonNode n=mapper.valueToTree(v);if(mapper.writeValueAsBytes(v).length>MAX_BYTES||depth(n)>MAX_DEPTH)throw bad("component JSON exceeds limits 256 KiB");}catch(BusinessException e){throw e;}catch(Exception e){throw bad("component JSON invalid");}}private int depth(JsonNode n){if(n==null||n.isValueNode())return 1;int m=0;for(JsonNode c:n)m=Math.max(m,depth(c));return m+1;}static String normalizeTemplate(String raw){if(raw==null||raw.isBlank())return null;String p=raw.trim().replace((char)92,'/');while(p.startsWith("/"))p=p.substring(1);if(p.contains("..")||!p.endsWith(".ftl")||!p.startsWith("templates/"))throw bad("invalid template path: must start with templates/");return p;}private static BusinessException bad(String m){return new BusinessException(ErrorCodes.VALIDATION_FAILED,m);}}
